-- Synthetic GA4-shaped sample for A1 Bench sql-ga4. Generated, not exported: no real users, sites or orders.
-- One week (2026-09-21..27), 60 pseudo users, shop.example.com. Regenerate with the seed in the comment: 20260921.
CREATE TABLE events (event_date TEXT, event_timestamp INTEGER, event_name TEXT, user_pseudo_id TEXT, session_id INTEGER,
  page_location TEXT, device_category TEXT, country TEXT, source TEXT, medium TEXT, value REAL, currency TEXT, transaction_id TEXT);
CREATE TABLE items (transaction_id TEXT, item_id TEXT, item_name TEXT, item_category TEXT, price REAL, quantity INTEGER);
